import { administrationStepTexts } from './i18n-administration-steps';
import { pathAssignmentTexts } from './i18n-path-assignments';
// Columns: it, en, es, fr, de, sv. Each key must provide all six translations.
const text = {
    teacherItalianAdministrationBody: administrationStepTexts.teacherGuide,
    teacherItalianAdministrationRule: administrationStepTexts.rule,
    teacherItalianAdministrationLogin: administrationStepTexts.loginHint,
    teacherInAppAdministrationBody: administrationStepTexts.teacherInAppGuide,
    teacherResultsDeepDiveBody: administrationStepTexts.deepDiveRule,
    teacherPathAssignmentBody: pathAssignmentTexts.rule,
    teacherInstituteCredentialsBody: ["Il codice e la password rilasciati da competenzestrategiche.it appartengono all’istituto: in Istituti un docente membro sceglie Inserisci credenziali esterne e salva. La password si può solo scrivere: CounselorBot conserva soltanto un verificatore, non la mostra più e non la recupera; consegna le credenziali agli studenti separatamente. Ogni piano di somministrazione sceglie l’istituto invece di salvare altre credenziali. Prima di salvare i risultati di un piano d’istituto lo studente inserisce codice e password; il controllo avviene solo in CounselorBot e non verifica nulla sul sito esterno. I piani precedenti ambigui sono segnalati come Da riconciliare finché lo staff non conferma l’istituto.", "The code and password issued by competenzestrategiche.it belong to the institute: in Institutes a member teacher chooses Enter external credentials and saves. The password is write-only: CounselorBot keeps only a verifier, never shows it again and cannot recover it; give students the login separately. Each administration plan selects the institute instead of storing other credentials. Before results of an institute plan are saved, the student enters the code and password; the check happens only inside CounselorBot and verifies nothing on the external site. Ambiguous earlier plans are marked Needs reconciliation until staff confirm the institute.", "El código y la contraseña emitidos por competenzestrategiche.it pertenecen al instituto: en Institutos un docente miembro elige Introducir credenciales externas y guarda. La contraseña solo se puede escribir: CounselorBot conserva únicamente un verificador, no vuelve a mostrarla ni puede recuperarla; entrega las credenciales a los estudiantes por separado. Cada plan de administración selecciona el instituto en lugar de guardar otras credenciales. Antes de guardar los resultados de un plan del instituto, el estudiante introduce el código y la contraseña; la comprobación ocurre solo en CounselorBot y no verifica nada en el sitio externo. Los planes anteriores ambiguos aparecen como Pendiente de conciliar hasta que el personal confirme el instituto.", "Le code et le mot de passe délivrés par competenzestrategiche.it appartiennent à l’établissement : dans Établissements, un enseignant membre choisit Saisir les identifiants externes puis enregistre. Le mot de passe est en écriture seule : CounselorBot ne garde qu’un vérificateur, ne le réaffiche jamais et ne peut pas le récupérer ; transmettez les identifiants aux élèves séparément. Chaque plan de passation choisit l’établissement au lieu d’enregistrer d’autres identifiants. Avant l’enregistrement des résultats d’un plan d’établissement, l’élève saisit le code et le mot de passe ; le contrôle a lieu uniquement dans CounselorBot et ne vérifie rien sur le site externe. Les anciens plans ambigus sont marqués À rapprocher jusqu’à la confirmation de l’établissement par l’équipe.", "Code und Passwort von competenzestrategiche.it gehören der Einrichtung: Unter Einrichtungen wählt eine Lehrkraft der Einrichtung Externe Zugangsdaten eingeben und speichert. Das Passwort kann nur geschrieben werden: CounselorBot speichert nur einen Prüfwert, zeigt es nie wieder an und kann es nicht wiederherstellen; geben Sie die Zugangsdaten den Lernenden separat. Jeder Durchführungsplan wählt die Einrichtung, statt eigene Zugangsdaten zu speichern. Bevor Ergebnisse eines Einrichtungsplans gespeichert werden, geben Lernende Code und Passwort ein; geprüft wird nur in CounselorBot, nicht auf der externen Website. Mehrdeutige ältere Pläne sind als Abgleich erforderlich markiert, bis das Team die Einrichtung bestätigt.", "Koden och lösenordet från competenzestrategiche.it tillhör lärosätet: under Lärosäten väljer en lärare som är medlem Ange externa inloggningsuppgifter och sparar. Lösenordet kan bara skrivas: CounselorBot behåller endast en verifierare, visar det aldrig igen och kan inte återställa det; ge eleverna inloggningen separat. Varje administreringsplan väljer lärosätet i stället för att spara egna uppgifter. Innan resultat från ett lärosätes plan sparas anger eleven koden och lösenordet; kontrollen sker bara i CounselorBot och verifierar inget på den externa webbplatsen. Tvetydiga äldre planer markeras som Behöver stämmas av tills personalen bekräftar lärosätet."],
    teacherInstitutesBody: ["Apri Area docenti → Istituti. Controlla l’elenco prima di creare un istituto: Salva lo attiva subito e ti associa come docente. Il secondo docente sceglie un istituto esistente e preme Aderisci all’istituto selezionato, senza invito, password o approvazione. Ogni istituto ammette due docenti; adesioni ripetute non duplicano la membership. Le associazioni precedenti oltre due restano valide e i duplicati saranno riconciliati dall’amministratore. Modifica nome, tipo e pagine pubbliche con Salva; un errore o conflitto conserva la bozza. Apri l’istituto per creare una classe già associata o collegare una tua classe senza istituto. L’adesione non dà accesso alle classi degli altri: proprietario e co-docenti mantengono autorizzazioni separate. Le classi senza istituto continuano a funzionare.", "Open Teacher area → Institutes. Check the directory before creating an institute: Save activates it immediately and creates your teacher membership. The second teacher selects an existing institute and chooses Join selected institute, without an invitation, password or approval. Each institute accepts two teachers; repeat joins do not duplicate membership. Existing memberships above two remain valid and the administrator reconciles duplicates later. Edit the name, type and public pages with Save; errors and conflicts preserve your draft. Open the institute to create a prelinked class or link one of your unlinked classes. Membership does not grant access to other teachers’ classes: owner and co-teacher permissions remain separate. Classes without an institute keep working.", "Abre Área docente → Institutos. Revisa la lista antes de crear un instituto: Guardar lo activa de inmediato y crea tu membresía docente. El segundo docente selecciona un instituto existente y pulsa Unirse al instituto seleccionado, sin invitación, contraseña ni aprobación. Cada instituto admite dos docentes; repetir la adhesión no duplica la membresía. Las membresías anteriores de más de dos docentes siguen vigentes y el administrador resolverá los duplicados después. Edita nombre, tipo y páginas públicas con Guardar; los errores y conflictos conservan tu borrador. Abre el instituto para crear una clase asociada o vincular una de tus clases sin instituto. La membresía no da acceso a las clases de otros docentes: los permisos del propietario y colaboradores siguen separados. Las clases sin instituto siguen funcionando.", "Ouvrez Espace enseignant → Établissements. Vérifiez la liste avant de créer un établissement : Enregistrer l’active immédiatement et vous associe comme enseignant. Le deuxième enseignant choisit un établissement existant et clique sur Rejoindre l’établissement sélectionné, sans invitation, mot de passe ni approbation. Chaque établissement accepte deux enseignants ; une adhésion répétée ne crée pas de doublon. Les associations anciennes de plus de deux enseignants restent valides et l’administrateur traitera les doublons ultérieurement. Modifiez le nom, le type et les pages publiques avec Enregistrer ; erreurs et conflits conservent le brouillon. Ouvrez l’établissement pour créer une classe associée ou lier une de vos classes sans établissement. L’adhésion ne donne pas accès aux classes des autres enseignants : propriétaire et coenseignants gardent des droits distincts. Les classes sans établissement continuent à fonctionner.", "Öffnen Sie Lehrkräftebereich → Einrichtungen. Prüfen Sie die Liste vor dem Erstellen: Speichern aktiviert die Einrichtung sofort und legt Ihre Mitgliedschaft an. Die zweite Lehrkraft wählt eine bestehende Einrichtung und klickt auf Ausgewählter Einrichtung beitreten, ohne Einladung, Passwort oder Genehmigung. Jede Einrichtung nimmt zwei Lehrkräfte auf; wiederholte Beitritte erzeugen keine Duplikate. Bestehende Mitgliedschaften mit mehr als zwei Lehrkräften bleiben gültig; Duplikate gleicht die Administration später ab. Name, Typ und öffentliche Seiten werden mit Speichern geändert; Fehler und Konflikte bewahren Ihren Entwurf. Öffnen Sie die Einrichtung, um eine zugeordnete Klasse zu erstellen oder eine eigene Klasse ohne Einrichtung zu verbinden. Mitgliedschaft gewährt keinen Zugang zu Klassen anderer Lehrkräfte: Klassenverantwortliche und mitwirkende Lehrkräfte behalten separate Rechte. Klassen ohne Einrichtung bleiben nutzbar.", "Öppna Lärarområde → Lärosäten. Kontrollera listan innan du skapar ett lärosäte: Spara aktiverar det direkt och ger dig lärarmedlemskap. Den andra läraren väljer ett befintligt lärosäte och klickar på Gå med i valt lärosäte, utan inbjudan, lösenord eller godkännande. Varje lärosäte tar emot två lärare; upprepade anslutningar skapar inte dubbla medlemskap. Befintliga medlemskap med fler än två lärare förblir giltiga och administratören hanterar dubbletter senare. Redigera namn, typ och offentliga sidor med Spara; fel och konflikter bevarar utkastet. Öppna lärosätet för att skapa en kopplad klass eller koppla en egen klass utan lärosäte. Medlemskap ger inte tillgång till andra lärares klasser: klassansvarig och medlärare behåller separata rättigheter. Klasser utan lärosäte fungerar fortfarande."],
    classSettingsTeacher: ["Apri Area docenti → Classi → Apri classe. Panoramica mostra codice e contesto della classe; in Strumenti e counselor il proprietario, i co-docenti e gli amministratori scelgono cosa rendere disponibile agli studenti. Le categorie comprendono questionari, chat guidate, strumenti personali, Bussola, Assistente e forum. Seleziona gli elementi o usa le azioni di categoria, poi premi Salva nella barra in fondo. Le nuove classi e i nuovi strumenti partono abilitati. Un errore conserva la bozza; se qualcuno ha salvato nel frattempo, Ricarica chiede conferma prima di scartarla.", "Open Teacher area → Classes → Open class. Overview shows the class code and context; in Tools & counselors the owner, co-teachers and administrators choose what students can use. Categories include questionnaires, guided chats, personal tools, Compass, Assistant and forum. Select items or use the category actions, then press Save in the bottom bar. New classes and new tools start enabled. A failure keeps your draft; if someone else has saved meanwhile, Reload asks before discarding it.", "Abre Área docente → Clases → Abrir clase. La vista general muestra el código y el contexto; en Herramientas y counselors el propietario, los docentes colaboradores y los administradores eligen lo que pueden usar los estudiantes. Las categorías incluyen cuestionarios, chats guiados, herramientas personales, Brújula, Asistente y foro. Selecciona elementos o usa las acciones de categoría y pulsa Guardar en la barra inferior. Las clases y herramientas nuevas empiezan habilitadas. Un error conserva el borrador; si otra persona ha guardado mientras tanto, Recargar pide confirmación antes de descartarlo.", "Ouvrez Espace enseignant → Classes → Ouvrir la classe. La vue d’ensemble affiche le code et le contexte ; dans Outils et counselors, le propriétaire, les coenseignants et les administrateurs choisissent ce que les étudiants peuvent utiliser. Les catégories comprennent questionnaires, discussions guidées, outils personnels, Boussole, Assistant et forum. Sélectionnez les éléments ou utilisez les actions de catégorie, puis Enregistrer dans la barre du bas. Les nouvelles classes et les nouveaux outils sont activés par défaut. Un échec conserve le brouillon ; si quelqu’un a enregistré entre-temps, Recharger demande confirmation avant de l’abandonner.", "Öffnen Sie Lehrkräftebereich → Klassen → Klasse öffnen. Die Übersicht zeigt Klassencode und Kontext; unter Werkzeuge und Counselor wählen Eigentümer, weitere Lehrkräfte und Administratoren, was Lernende nutzen können. Die Kategorien umfassen Fragebögen, geführte Chats, persönliche Werkzeuge, Kompass, Assistent und Forum. Wählen Sie Einträge oder nutzen Sie die Kategorieaktionen und drücken Sie unten Speichern. Neue Klassen und Werkzeuge sind zunächst aktiviert. Bei Fehlern bleibt der Entwurf erhalten; hat inzwischen jemand gespeichert, fragt Neu laden vor dem Verwerfen nach.", "Öppna Lärarområdet → Klasser → Öppna klass. Översikten visar klassens kod och sammanhang; under Verktyg och counselor väljer ägaren, medlärarna och administratörerna vad elever kan använda. Kategorierna omfattar enkäter, vägledda chattar, personliga verktyg, Kompass, Assistent och forum. Välj objekt eller använd kategoriåtgärderna och tryck sedan Spara i raden längst ned. Nya klasser och verktyg är aktiverade från början. Ett fel bevarar utkastet; om någon annan har sparat under tiden ber Ladda om om bekräftelse innan det kastas."],
    classSettingsAccess: ["Il catalogo e i collegamenti dell’Area personale dipendono dalle impostazioni delle tue classi attive: basta che almeno una abiliti uno strumento perché sia disponibile. Senza classi attive si applica il catalogo della piattaforma. Una disattivazione globale prevale sempre. Taccuino, Compilazioni, Classi e Assegnazioni restano disponibili. Se uno strumento viene disabilitato, il lavoro già salvato resta leggibile, ma non puoi iniziare nuovo lavoro o riprendere una sessione congelata. I filtri di classe non limitano docenti, ricercatori o amministratori. Se manca uno strumento, chiedi al docente di verificare le impostazioni.", "The catalog and Personal area links depend on your active classes: a tool is available if at least one class enables it. With no active class, the platform catalog applies. A platform-wide disable always takes precedence. Notebook, completed questionnaires, Classes and Assignments stay available. When a tool is disabled, saved work remains readable, but you cannot start new work or resume a frozen session. Class filters do not restrict teachers, researchers or administrators. If a tool is missing, ask your teacher to check the settings.", "El catálogo y los enlaces del Área personal dependen de tus clases activas: basta con que una habilite una herramienta para que esté disponible. Sin clases activas se aplica el catálogo de la plataforma. Una desactivación global siempre prevalece. Cuaderno, cuestionarios completados, Clases y Tareas siguen disponibles. Al deshabilitar una herramienta, el trabajo guardado sigue siendo legible, pero no puedes empezar trabajo nuevo ni reanudar una sesión congelada. Los filtros de clase no limitan a docentes, investigadores o administradores. Si falta una herramienta, pide al docente que revise las opciones.", "Le catalogue et les liens de l’Espace personnel dépendent de vos classes actives : un outil est disponible si au moins une classe l’autorise. Sans classe active, le catalogue de la plateforme s’applique. Une désactivation globale prévaut toujours. Carnet, questionnaires terminés, Classes et Travaux attribués restent disponibles. Si un outil est désactivé, le travail enregistré reste lisible, mais vous ne pouvez pas commencer un nouveau travail ni reprendre une session gelée. Les filtres de classe ne limitent pas les enseignants, chercheurs ou administrateurs. Si un outil manque, demandez à l’enseignant de vérifier les paramètres.", "Katalog und Links im persönlichen Bereich hängen von Ihren aktiven Klassen ab: Ein Werkzeug ist verfügbar, wenn mindestens eine Klasse es freigibt. Ohne aktive Klasse gilt der Plattformkatalog. Eine globale Deaktivierung hat immer Vorrang. Notizbuch, abgeschlossene Fragebögen, Klassen und Aufgaben bleiben verfügbar. Wird ein Werkzeug deaktiviert, bleiben gespeicherte Arbeiten lesbar; neue Arbeiten und das Fortsetzen eingefrorener Sitzungen sind gesperrt. Klassenfilter beschränken Lehrkräfte, Forschende und Administratoren nicht. Fehlt ein Werkzeug, bitten Sie die Lehrkraft, die Einstellungen zu prüfen.", "Katalogen och länkarna i det personliga området beror på dina aktiva klasser: ett verktyg är tillgängligt om minst en klass tillåter det. Utan aktiv klass gäller plattformens katalog. En avstängning för hela plattformen har alltid företräde. Anteckningsbok, slutförda enkäter, Klasser och Uppgifter finns kvar. När ett verktyg stängs av går sparat arbete fortfarande att läsa, men du kan inte börja nytt arbete eller återuppta en fryst session. Klassfilter begränsar inte lärare, forskare eller administratörer. Om ett verktyg saknas, be läraren kontrollera inställningarna."],
    classViewSwitch: ["Se fai parte di almeno una classe, il selettore Vista attiva nella barra in alto sceglie cosa vedi: la vista di classe (predefinita; con più classi, Le mie classi unisce le loro impostazioni, oppure scegli una sola classe) o Tutti gli strumenti, che mostra ogni strumento e counselor della piattaforma. Le impostazioni della classe sono un consiglio, non un blocco. La scelta è salvata nel tuo account e vale su ogni dispositivo e su Telegram. Percorsi di classe e forum seguono sempre le impostazioni della loro classe.", "If you belong to at least one class, the Active view selector in the top bar chooses what you see: the class view (default; with several classes, My classes combines their settings, or pick a single class) or All tools, which shows every platform tool and counselor. Class settings are a recommendation, not a block. Your choice is saved in your account and applies on every device and on Telegram. Class paths and forums always follow their own class settings.", "Si perteneces al menos a una clase, el selector Vista activa de la barra superior elige lo que ves: la vista de clase (predeterminada; con varias clases, Mis clases combina sus opciones, o elige una sola clase) o Todas las herramientas, que muestra todas las herramientas y counselors de la plataforma. Las opciones de la clase son una recomendación, no un bloqueo. Tu elección se guarda en tu cuenta y vale en todos los dispositivos y en Telegram. Los recorridos de clase y los foros siguen siempre las opciones de su clase.", "Si vous appartenez à au moins une classe, le sélecteur Vue active de la barre supérieure choisit ce que vous voyez : la vue de classe (par défaut ; avec plusieurs classes, Mes classes combine leurs paramètres, ou choisissez une seule classe) ou Tous les outils, qui affiche tous les outils et counselors de la plateforme. Les paramètres de la classe sont une recommandation, pas un blocage. Votre choix est enregistré dans votre compte et s’applique sur tous les appareils et sur Telegram. Les parcours de classe et les forums suivent toujours les paramètres de leur classe.", "Wenn Sie mindestens einer Klasse angehören, legt die Auswahl Aktive Ansicht in der oberen Leiste fest, was Sie sehen: die Klassenansicht (Standard; bei mehreren Klassen fasst Meine Klassen deren Einstellungen zusammen, oder wählen Sie eine einzelne Klasse) oder Alle Werkzeuge mit allen Werkzeugen und Counselors der Plattform. Klasseneinstellungen sind eine Empfehlung, keine Sperre. Ihre Wahl wird in Ihrem Konto gespeichert und gilt auf allen Geräten und in Telegram. Klassenpfade und Foren folgen immer den Einstellungen ihrer Klasse.", "Om du tillhör minst en klass väljer Aktiv vy i det övre fältet vad du ser: klassvyn (standard; med flera klasser kombinerar Mina klasser deras inställningar, eller välj en enda klass) eller Alla verktyg, som visar alla plattformens verktyg och counselors. Klassens inställningar är en rekommendation, inte en spärr. Ditt val sparas i ditt konto och gäller på alla enheter och i Telegram. Klassvägar och forum följer alltid sin egen klass inställningar."],
    classSettingsCounselors: ["Il docente può abilitare i counselor dell’istituzione e scegliere un counselor predefinito per la classe. Con più classi attive, basta che una abiliti un counselor; la disattivazione globale prevale. I tuoi counselor privati non sono filtrati dalla classe. Se il counselor salvato nell’account non è più consentito, al prossimo avvio viene usato un predefinito di classe consentito e adatto allo strumento, quando disponibile; altrimenti scegli tra quelli consentiti. Senza counselor disponibili, contatta il docente. Le conversazioni precedenti restano leggibili.", "The teacher can enable institutional counselors and choose a class default. Across active classes, a counselor is allowed if at least one class enables it; a platform-wide disable takes precedence. Your private counselors are exempt from class filters. If your saved account counselor is no longer allowed, the next start uses an allowed class default suitable for the tool when available; otherwise you choose from allowed counselors. If none are available, contact your teacher. Earlier conversations remain readable.", "El docente puede habilitar counselors de la institución y elegir uno predeterminado para la clase. Entre las clases activas, basta con que una habilite un counselor; una desactivación global prevalece. Tus counselors privados quedan fuera de los filtros de clase. Si el counselor guardado en tu cuenta ya no está permitido, el siguiente inicio usa un predeterminado de clase permitido y adecuado a la herramienta, si existe; de lo contrario eliges entre los permitidos. Si no hay ninguno, contacta con el docente. Las conversaciones anteriores siguen siendo legibles.", "L’enseignant peut activer les counselors de l’établissement et choisir celui par défaut pour la classe. Parmi les classes actives, il suffit qu’une classe autorise un counselor ; une désactivation globale prévaut. Vos counselors privés échappent aux filtres de classe. Si celui enregistré dans votre compte n’est plus autorisé, le prochain démarrage utilise un counselor de classe par défaut autorisé et adapté à l’outil, si disponible ; sinon, vous choisissez parmi ceux autorisés. Si aucun n’est disponible, contactez l’enseignant. Les conversations précédentes restent lisibles.", "Die Lehrkraft kann institutionelle Counselor freigeben und einen Klassenstandard wählen. Bei mehreren aktiven Klassen genügt die Freigabe durch eine Klasse; globale Deaktivierungen haben Vorrang. Ihre privaten Counselor unterliegen keinem Klassenfilter. Ist Ihr gespeicherter Counselor nicht mehr erlaubt, nutzt der nächste Start einen erlaubten, zum Werkzeug passenden Klassenstandard, sofern verfügbar; andernfalls wählen Sie aus den erlaubten Counselorn. Ist keiner verfügbar, wenden Sie sich an die Lehrkraft. Frühere Gespräche bleiben lesbar.", "Läraren kan aktivera institutionens counselor och välja en standard för klassen. Bland aktiva klasser räcker det att en tillåter en counselor; en avstängning för hela plattformen har företräde. Dina privata counselor omfattas inte av klassfilter. Om den som sparats i ditt konto inte längre tillåts använder nästa start en tillåten klassstandard som passar verktyget, om det finns någon; annars väljer du bland de tillåtna. Kontakta läraren om ingen finns tillgänglig. Tidigare samtal går fortfarande att läsa."],
    classSettingsHistory: ["Un elemento bloccato dall’amministratore è indicato come attivo o disattivo e non può essere cambiato dal docente. Gli elementi modificati dall’amministratore sono segnalati. Apri Registro modifiche per vedere autore, data, valore precedente e nuovo e l’eventuale motivo: la cronologia è consultabile dal proprietario, dai co-docenti e dagli amministratori. Le opzioni del forum regolano apertura delle discussioni da parte degli studenti e approvazione preventiva; la moderazione di messaggi e discussioni ha un registro separato nella scheda Forum.", "An administrator-locked item shows its forced enabled or disabled state and cannot be changed by teachers. Items changed by an administrator are marked. Open Change history to see who changed what, when, the old and new values and any reason: owners, co-teachers and administrators can read this history. Forum options govern student-created discussions and pre-approval; moderation of messages and discussions has a separate log in the Forum tab.", "Un elemento bloqueado por el administrador muestra su estado forzado, activado o desactivado, y los docentes no pueden cambiarlo. Los elementos modificados por el administrador están marcados. Abre Historial de cambios para consultar autor, fecha, valores anteriores y nuevos y el motivo, si existe: pueden leerlo el propietario, los docentes colaboradores y los administradores. Las opciones del foro regulan las discusiones creadas por estudiantes y la aprobación previa; la moderación de mensajes y discusiones tiene un registro separado en la pestaña Foro.", "Un élément verrouillé par l’administrateur affiche son état imposé, activé ou désactivé, et les enseignants ne peuvent pas le modifier. Les éléments modifiés par l’administrateur sont signalés. Ouvrez Historique des modifications pour consulter auteur, date, anciennes et nouvelles valeurs et motif éventuel : propriétaire, coenseignants et administrateurs peuvent le lire. Les options du forum règlent l’ouverture de discussions par les étudiants et l’approbation préalable ; la modération des messages et discussions possède un journal distinct dans l’onglet Forum.", "Ein administrativ gesperrter Eintrag zeigt seinen erzwungenen Zustand, aktiviert oder deaktiviert, und kann von Lehrkräften nicht geändert werden. Administrativ geänderte Einträge sind markiert. Öffnen Sie Änderungsverlauf für Person, Zeitpunkt, alte und neue Werte sowie einen möglichen Grund: Eigentümer, weitere Lehrkräfte und Administratoren können den Verlauf lesen. Forumoptionen regeln das Eröffnen von Diskussionen durch Lernende und die Vorabfreigabe; die Moderation von Nachrichten und Diskussionen hat ein eigenes Protokoll im Forum.", "Ett administratörslåst objekt visar sitt tvingade läge, på eller av, och kan inte ändras av lärare. Objekt som ändrats av administratören är markerade. Öppna Ändringshistorik för att se vem, när, gamla och nya värden samt eventuell orsak: ägare, medlärare och administratörer kan läsa historiken. Forumalternativen styr om elever får öppna diskussioner och om förhandsgodkännande krävs; moderering av meddelanden och diskussioner har en separat logg under Forum."],
    classPathDistinction: ["Le impostazioni decidono quali strumenti sono disponibili. La scheda Percorsi di classe serve invece a organizzare una sequenza di attività per la classe: è distinta dal percorso guidato interno a un singolo strumento. Un passo vincolato nel percorso di classe non disabilita lo strumento nel catalogo.", "Settings decide which tools are available. The Class paths tab organizes a sequence of activities for the class; it is separate from the guided path inside a single instrument. A locked class-path step does not disable its tool in the catalog.", "Las opciones deciden qué herramientas están disponibles. La pestaña Itinerarios de clase organiza una secuencia de actividades para la clase; es distinta del recorrido guiado dentro de una sola herramienta. Un paso bloqueado del itinerario no deshabilita la herramienta en el catálogo.", "Les paramètres décident des outils disponibles. L’onglet Parcours de classe organise une suite d’activités pour la classe ; il est distinct du parcours guidé interne à un seul outil. Une étape verrouillée du parcours de classe ne désactive pas son outil dans le catalogue.", "Die Einstellungen bestimmen die verfügbaren Werkzeuge. Klassenpfade ordnen Aktivitäten für die Klasse; sie unterscheiden sich vom geführten Ablauf innerhalb eines einzelnen Instruments. Ein gesperrter Klassenpfadschritt deaktiviert das Werkzeug im Katalog nicht.", "Inställningarna avgör vilka verktyg som är tillgängliga. Under Klassvägar ordnas en följd av aktiviteter för klassen; det är skilt från den vägledda processen inom ett enskilt verktyg. Ett låst steg i klassvägen stänger inte av verktyget i katalogen."],
    classSettingsAdmin: ["Apri Amministrazione → Gruppi e classi, oppure /admin/classi, per vedere tutte le classi. Cerca per nome, codice o scuola e filtra per docente proprietario, istituzione e stato, poi premi Filtra. Impostazioni e blocchi apre /admin/classi/{id}: puoi modificare gli stessi strumenti, counselor e opzioni del forum e salvare esplicitamente, con un motivo facoltativo. Blocca attivo o Blocca disattivo forza un singolo elemento e impedisce le modifiche del proprietario e dei co-docenti; Sblocca restituisce loro la possibilità di cambiarlo. I blocchi si applicano subito: salva o ricarica prima una bozza modificata. Non puoi forzare attivo uno strumento o counselor disabilitato globalmente. Registro modifiche conserva in sola lettura ogni modifica e blocco/sblocco, con autore, data, valori precedenti e nuovi e motivo. I blocchi riguardano impostazioni della classe, non singoli passi del percorso o messaggi del forum.", "Open Administration → Groups and classes, or /admin/classi, to see all classes. Search by name, code or school and filter by owner teacher, institution and status, then press Filter. Settings & locks opens /admin/classi/{id}: edit the same tools, counselors and forum options and save explicitly, with an optional reason. Lock ON or Lock OFF forces an individual item and prevents changes by owners and co-teachers; Unlock lets them edit it again. Locks apply immediately: save or reload a dirty draft first. You cannot force ON a globally disabled tool or counselor. Change history keeps a read-only record of every change and lock/unlock, with author, date, old and new values and reason. Locks concern class settings, not individual path steps or forum messages.", "Abre Administración → Grupos y clases, o /admin/classi, para ver todas las clases. Busca por nombre, código o escuela y filtra por docente propietario, institución y estado; pulsa Filtrar. Opciones y bloqueos abre /admin/classi/{id}: edita las mismas herramientas, counselors y opciones del foro y guarda explícitamente, con un motivo opcional. Bloquear activado o Bloquear desactivado fuerza un elemento e impide que el propietario y los docentes colaboradores lo cambien; Desbloquear permite que vuelvan a editarlo. Los bloqueos son inmediatos: guarda o recarga antes un borrador modificado. No puedes forzar la activación de una herramienta o counselor desactivado globalmente. El historial conserva un registro de solo lectura de cada cambio y bloqueo/desbloqueo, con autor, fecha, valores anteriores y nuevos y motivo. Los bloqueos afectan a las opciones de clase, no a pasos individuales ni mensajes del foro.", "Ouvrez Administration → Groupes et classes, ou /admin/classi, pour voir toutes les classes. Recherchez par nom, code ou école et filtrez par enseignant propriétaire, établissement et état, puis Filtrer. Paramètres et verrouillages ouvre /admin/classi/{id} : modifiez les mêmes outils, counselors et options du forum, puis enregistrez explicitement avec un motif facultatif. Verrouiller activé ou Verrouiller désactivé impose l’état d’un élément et empêche le propriétaire et les coenseignants de le modifier ; Déverrouiller leur rend cette possibilité. Les verrouillages sont immédiats : enregistrez ou rechargez d’abord un brouillon modifié. Vous ne pouvez pas imposer l’activation d’un outil ou counselor désactivé globalement. L’historique conserve en lecture seule chaque modification et verrouillage/déverrouillage, avec auteur, date, anciennes et nouvelles valeurs et motif. Ces verrouillages concernent les paramètres de classe, pas les étapes individuelles ni les messages du forum.", "Öffnen Sie Verwaltung → Gruppen und Klassen oder /admin/classi für alle Klassen. Suchen Sie nach Name, Code oder Schule und filtern Sie nach verantwortlicher Lehrkraft, Institution und Status; drücken Sie Filtern. Einstellungen und Sperren öffnet /admin/classi/{id}: Bearbeiten Sie dieselben Werkzeuge, Counselor und Forumoptionen und speichern Sie ausdrücklich, optional mit Grund. Aktiviert sperren oder Deaktiviert sperren erzwingt einen Eintrag und verhindert Änderungen durch Eigentümer und weitere Lehrkräfte; Entsperren gibt die Bearbeitung wieder frei. Sperren gelten sofort: Speichern oder laden Sie einen geänderten Entwurf zuerst neu. Global deaktivierte Werkzeuge oder Counselor können nicht zwangsweise aktiviert werden. Der Änderungsverlauf hält jede Änderung und Sperrung/Entsperrung mit Person, Datum, alten und neuen Werten sowie Grund schreibgeschützt fest. Sperren betreffen Klasseneinstellungen, keine einzelnen Pfadschritte oder Forumnachrichten.", "Öppna Administration → Grupper och klasser eller /admin/classi för att se alla klasser. Sök på namn, kod eller skola och filtrera efter ägande lärare, institution och status; tryck sedan Filtrera. Inställningar och lås öppnar /admin/classi/{id}: ändra samma verktyg, counselor och forumalternativ och spara uttryckligen, med valfri orsak. Lås på eller Lås av tvingar ett objekt och hindrar ägaren och medlärarna från att ändra det; Lås upp låter dem ändra det igen. Lås gäller direkt: spara eller ladda om ett ändrat utkast först. Ett verktyg eller en counselor som stängts av för hela plattformen kan inte tvingas på. Ändringshistoriken bevarar varje ändring och låsning/upplåsning med vem, datum, gamla och nya värden samt orsak och kan bara läsas. Låsen gäller klassinställningar, inte enskilda steg eller forummeddelanden."],

    audience: ['Scegli la guida', 'Choose your guide', 'Elige la guía', 'Choisir le guide', 'Anleitung wählen', 'Välj guide'],
    student: ['Uso personale / studente', 'Personal use / student', 'Uso personal / estudiante', 'Usage personnel / étudiant', 'Persönliche Nutzung / Lernende', 'Personligt bruk / elev'],
    teacher: ['Docente', 'Teacher', 'Docente', 'Enseignant', 'Lehrkraft', 'Lärare'],
    studentIntro: ['Per usare CounselorBot in autonomia o come studente: scegli strumenti, coltiva obiettivi e documenta il tuo percorso.', 'Use CounselorBot independently or as a student: choose tools, develop goals and document your journey.', 'Usa CounselorBot de forma autónoma o como estudiante: elige herramientas, desarrolla objetivos y documenta tu recorrido.', 'Utilisez CounselorBot en autonomie ou comme étudiant : choisissez des outils, développez des objectifs et documentez votre parcours.', 'Nutzen Sie CounselorBot selbstständig oder als Lernende: Wählen Sie Werkzeuge, entwickeln Sie Ziele und dokumentieren Sie Ihren Weg.', 'Använd CounselorBot på egen hand eller som elev: välj verktyg, utveckla mål och dokumentera din väg.'],
    teacherIntro: ['Per accompagnare persone, gruppi e classi: prepara proposte, assegna materiali e restituisci riscontri. La scelta della guida non modifica i permessi del tuo account.', 'Support individuals, groups and classes: prepare proposals, assign resources and provide feedback. Choosing a guide does not change your account permissions.', 'Acompaña a personas, grupos y clases: prepara propuestas, asigna materiales y ofrece comentarios. Elegir la guía no cambia los permisos de tu cuenta.', 'Accompagnez des personnes, groupes et classes : préparez des propositions, attribuez des ressources et apportez des retours. Le choix du guide ne modifie pas les droits du compte.', 'Begleiten Sie Personen, Gruppen und Klassen: Bereiten Sie Vorschläge vor, weisen Sie Materialien zu und geben Sie Rückmeldungen. Die Wahl der Anleitung ändert keine Kontoberechtigungen.', 'Stöd personer, grupper och klasser: förbered förslag, tilldela material och ge återkoppling. Valet av guide ändrar inte kontots behörigheter.'],
    screenshots: ['Schermate dell’applicazione con dati dimostrativi. Le tre immagini della chat mostrano l’interfaccia italiana; le altre seguono la lingua della guida. Premi un’immagine per ingrandirla.', 'Application screenshots with demonstration data. The three chat images show the Italian interface; the others follow the guide language. Select an image to enlarge it.', 'Capturas de la aplicación con datos de ejemplo. Las tres imágenes del chat muestran la interfaz italiana; las demás siguen el idioma de la guía. Pulsa una imagen para ampliarla.', 'Captures de l’application avec des données de démonstration. Les trois images du chat montrent l’interface italienne ; les autres suivent la langue du guide. Cliquez sur une image pour l’agrandir.', 'Anwendungsansichten mit Beispieldaten. Die drei Chatbilder zeigen die italienische Oberfläche; die übrigen folgen der Sprache der Anleitung. Wählen Sie ein Bild zum Vergrößern.', 'Skärmbilder från appen med demonstrationsdata. De tre chattbilderna visar det italienska gränssnittet; övriga följer guidens språk. Välj en bild för att förstora den.'],
    open: ['Apri questa area', 'Open this area', 'Abrir esta área', 'Ouvrir cet espace', 'Diesen Bereich öffnen', 'Öppna området'],
    personalGroups: ['In “I miei gruppi/classi” trovi le tue iscrizioni e puoi entrare con un codice di invito o lasciare un gruppo. Qui sei un partecipante anche se il tuo account è docente. I gestori del gruppo possono consultare Taccuino, risultati e relative conversazioni. La condivisione del riepilogo di un obiettivo e quella di una restituzione sono scelte separate e revocabili. Le bozze delle restituzioni e gli obiettivi collegati restano privati nel flusso delle assegnazioni. Per gestire gruppi e materiali consulta la versione Docente della guida.', '“My groups/classes” lists your memberships. Join with an invitation code or leave a group. Here you are a participant even if your account is a teacher. Group managers can access the Notebook, results and related conversations. Sharing a goal summary and sharing a response are separate, revocable choices. Response drafts and linked goals remain private within the assignment workflow. For group and resource management, choose the Teacher guide.', 'En “Mis grupos/clases” encontrarás tus inscripciones. Puedes entrar con un código de invitación o salir de un grupo. Aquí participas aunque tu cuenta sea docente. Los responsables del grupo pueden consultar el Cuaderno, los resultados y las conversaciones relacionadas. Compartir el resumen de un objetivo y compartir una entrega son decisiones separadas y revocables. Los borradores y objetivos vinculados siguen siendo privados en las asignaciones. Para gestionar grupos y materiales, elige la guía Docente.', '« Mes groupes/classes » répertorie vos inscriptions. Rejoignez un groupe avec un code ou quittez-le. Vous y êtes participant même avec un compte enseignant. Les responsables du groupe peuvent consulter le Carnet, les résultats et les conversations associées. Partager le bilan d’un objectif et partager un travail sont des choix distincts et révocables. Les brouillons et objectifs liés restent privés dans le suivi des travaux attribués. Pour gérer groupes et ressources, choisissez le guide Enseignant.', 'Unter „Meine Gruppen/Klassen“ finden Sie Ihre Mitgliedschaften. Treten Sie mit einem Einladungscode bei oder verlassen Sie eine Gruppe. Hier sind Sie auch mit einem Lehrkraftkonto Teilnehmer. Gruppenverantwortliche können Notizbuch, Ergebnisse und zugehörige Gespräche einsehen. Das Teilen einer Zielzusammenfassung und einer Abgabe sind getrennte, widerrufbare Entscheidungen. Entwürfe und verknüpfte Ziele bleiben im Zuweisungsablauf privat. Zur Verwaltung von Gruppen und Materialien wählen Sie die Anleitung für Lehrkräfte.', '”Mina grupper/klasser” visar dina medlemskap. Gå med med en inbjudningskod eller lämna en grupp. Här är du deltagare även om kontot är ett lärarkonto. Gruppansvariga kan se Anteckningsboken, resultat och tillhörande samtal. Att dela en målsammanfattning och att dela en redovisning är separata val som kan återkallas. Utkast och länkade mål förblir privata i tilldelningsflödet. Välj lärarguiden för hantering av grupper och material.'],
    teacher1Title: ['Entrare nell’Area docenti', 'Enter the teacher area', 'Entrar en el área docente', 'Accéder à l’espace enseignant', 'Den Lehrkräftebereich öffnen', 'Öppna lärarområdet'],
    teacher1Body: ["Nell’Area docenti, “Taccuino del docente” è il primo ingresso, prima del percorso DOCENZA e degli altri collegamenti. Aprilo per la pagina dedicata /docente/taccuino; la freccia nell’intestazione torna all’Area docenti. Il Taccuino dell’Area personale rimane separato. Accedi con un account abilitato come docente e apri “Area docenti” dalla navigazione. Qui trovi cataloghi, assegnazioni inviate, gruppi e somministrazioni. L’Area personale rimane il tuo spazio di partecipante e di riflessione. Il ruolo docente di CounselorBot non concede automaticamente l’accesso all’amministrazione tecnica o agli altri servizi ai4educ. Il Taccuino del docente descrive il tuo ruolo e la pratica abituale con sei campi facoltativi: discipline, esperienza sintetica, come insegni di solito, panoramica degli incarichi, interessi per la tua crescita e altre informazioni sul ruolo. La pratica generale è distinta dal Contesto classe, un interesse personale da un obiettivo per la classe, una nota breve da un episodio o un lavoro da conservare. Le note non gestiscono classi e non pubblicano cataloghi. Salva esplicitamente. Gli obiettivi per la classe usano per default il taccuino docente, gli altri strumenti quello dello studente; nelle Opzioni scegli Predefinito, Studente, Docente, Prova o Nessuno. Con Prova usi uno dei tuoi Taccuini di prova (/docente/taccuini-prova): uno studente immaginario per allenarti a guidare la chat, anche nella Bussola; il modello riceve l’istruzione esplicita che si tratta di una simulazione e i tuoi dati restano fuori. La scelta non riguarda tutti i dati della conversazione: la Lettura è distinta e Nessuno non significa anonimato. Il contesto è sintetico e può non includere tutte le note per intero: esplicita in chat i dettagli rilevanti. Puoi lasciare il taccuino vuoto; le classi selezionate possono comunque contribuire negli obiettivi per la classe, secondo il contesto scelto. Sotto gli hint del Taccuino del docente trovi rimandi volontari a Gruppi e classi, Obiettivi personali, Linea del tempo e Portfolio. Gruppi e classi apre una finestra senza uscire dal taccuino: scegli esplicitamente una classe gestita o condivisa, mai inferita dalle note. Nome, scuola/ente, proprietario e iscritti sono in sola lettura. Fascia e istituto si salvano al cambio; descrizione, metodologie e condivisione contesto richiedono Salva. Annulla scarta solo la bozza del contesto, non fascia o istituto già salvati. Cambio classe e chiusura chiedono conferma se il contesto è modificato e attendono ogni salvataggio; un errore conserva la bozza e offre Riprova. La bozza privata del taccuino rimane montata e conservata. Scegliere una classe qui non cambia sessione, taccuino usato nella chat o contesto della conversazione. La pagina Classi resta nella navigazione. Gli altri tre rimandi continuano a navigare senza copiare note, creare, salvare, pubblicare o condividere contenuti. Gli obiettivi personali riguardano la tua crescita, distinta dal percorso per la classe in alto. Con modifiche private non salvate, conferma lo scarto per uscire o annulla per conservare testo, focus e selezione; attendi il salvataggio in corso. Una bozza pulita passa senza conferme; una nuova scheda conserva la bozza nel tab originale. I sei campi sono raccolti in tre gruppi sempre aperti: «Il mio ruolo» (discipline ed esperienza), «La mia pratica e i miei contesti» (pratica abituale e incarichi), «La mia crescita e altre informazioni» (interessi e note). Tutti i campi restano visibili e facoltativi; i gruppi non impongono un percorso.", "In the Teacher area, “Teacher notebook” is the first entry, before the DOCENZA path and the other links. Open it for the dedicated /docente/taccuino page; the header arrow returns to the Teacher area. The Personal area notebook stays separate. Sign in with an account enabled for teaching and open the teacher area from the navigation. It contains catalogs, sent assignments, groups and assessment administrations. Your personal area remains your space as a participant and for reflection. The CounselorBot teacher role does not automatically grant access to technical administration or other ai4educ services. The Teacher notebook describes your role and usual practice through six optional fields: subjects, brief experience, how you usually teach, overview of roles, interests for your own development and other role information. General practice differs from Class context, a personal interest from a class objective, and a brief note from an episode or work to keep. Notes do not manage classes or publish catalogs. Save explicitly. Class objectives default to the teacher notebook, other tools to the student notebook; in Options choose Default, Student, Teacher, Practice or None. Practice uses one of your Practice notebooks (/docente/taccuini-prova): an imaginary student for rehearsing how you guide the chat, in the Compass too; the model receives an explicit instruction that it is a simulation and your own data stay out. The choice does not cover all conversation data: Reading is separate and None does not mean anonymity. Context is brief and may not include all notes in full: state relevant details in chat. You can leave the notebook empty; selected classes can still contribute to class objectives, depending on the chosen context. Under the teacher notebook hints, optional links open Groups and classes, Personal goals, Timeline and Portfolio. Groups and classes opens a dialog while keeping the notebook open: explicitly choose a managed or shared class, never inferred from notes. Name, school/organization, owner and member count are read-only. Level and institution save when changed; description, methodologies and context sharing require Save. Cancel discards only the context draft, not level or institution already saved. Switching class or closing asks for confirmation when context is dirty and waits for every save; failures keep the draft and offer Retry. The private notebook draft stays mounted and preserved. This class choice does not change the session, notebook used by chat or conversation context. The Classes page remains in navigation. The other three links still navigate without copying notes or creating, saving, publishing or sharing content. Personal goals concern your development, separate from the class path at the top. With unsaved private changes, confirm discarding to leave or cancel to keep text, focus and selection; wait for a pending save. A clean draft needs no confirmation; a new tab preserves the draft in the original tab. The six fields are arranged in three always-open groups: “My role” (subjects and experience), “My practice and settings” (usual practice and roles), “My development and other information” (interests and notes). All fields remain visible and optional; the groups do not impose a sequence.", "En el Área docente, “Cuaderno del docente” es la primera entrada, antes del recorrido DOCENZA y de los demás enlaces. Ábrelo para la página dedicada /docente/taccuino; la flecha del encabezado vuelve al Área docente. El Cuaderno del Área personal sigue separado. Accede con una cuenta habilitada como docente y abre el área docente desde la navegación. Allí encontrarás catálogos, asignaciones enviadas, grupos y administraciones de cuestionarios. El área personal sigue siendo tu espacio de participación y reflexión. El rol docente de CounselorBot no concede automáticamente acceso a la administración técnica ni a otros servicios ai4educ. El Cuaderno del docente describe tu rol y tu práctica habitual con seis campos opcionales: materias, experiencia breve, cómo enseñas, panorama de cargos, intereses para tu propio desarrollo y otra información sobre el rol. La práctica general es distinta del Contexto de clase, un interés personal de un objetivo para la clase, y una nota breve de un episodio o trabajo que conservar. Las notas no gestionan clases ni publican catálogos. Guarda explícitamente. Los objetivos para la clase usan por defecto el cuaderno docente, las demás herramientas el del estudiante; en Opciones elige Predeterminado, Estudiante, Docente, Práctica o Ninguno. Práctica usa uno de tus Cuadernos de práctica (/docente/taccuini-prova): un estudiante imaginario para ensayar cómo guías el chat, también en la Brújula; el modelo recibe la instrucción explícita de que es una simulación y tus datos quedan fuera. La elección no abarca todos los datos de la conversación: la Lectura es distinta y Ninguno no significa anonimato. El contexto es breve y puede no incluir todas las notas completas: explicita en la conversación los detalles relevantes. Puedes dejar el cuaderno vacío; las clases seleccionadas pueden contribuir a los objetivos para la clase, según el contexto elegido. Bajo las indicaciones del cuaderno docente hay enlaces voluntarios a Grupos y clases, Objetivos personales, Línea del tiempo y Portafolio. Grupos y clases abre una ventana sin salir del cuaderno: elige explícitamente una clase gestionada o compartida, nunca inferida de las notas. Nombre, escuela/entidad, propietario e inscritos son de solo lectura. La franja y el instituto se guardan al cambiarlos; descripción, metodologías y contexto compartido requieren Guardar. Cancelar descarta solo el borrador del contexto, no la franja ni el instituto ya guardados. Cambiar de clase o cerrar pide confirmación si el contexto tiene cambios y espera todos los guardados; un fallo conserva el borrador y permite reintentar. El borrador privado del cuaderno sigue montado y conservado. Esta elección no cambia sesión, cuaderno del chat ni contexto de la conversación. La página Clases sigue en la navegación. Los otros tres enlaces siguen navegando sin copiar notas ni crear, guardar, publicar o compartir contenido. Los objetivos personales son para tu desarrollo, separado del recorrido para la clase arriba. Con cambios privados, confirma descartarlos para salir o cancela para conservar texto, foco y selección; espera el guardado en curso. Un borrador limpio no pide confirmación; otra pestaña conserva el borrador original. Los seis campos se reúnen en tres grupos siempre abiertos: «Mi rol» (materias y experiencia), «Mi práctica y mis contextos» (práctica habitual y cargos), «Mi desarrollo y otra información» (intereses y notas). Todos los campos siguen visibles y opcionales; los grupos no imponen un recorrido.", "Dans l’Espace enseignant, « Carnet de l’enseignant » est la première entrée, avant le parcours DOCENZA et les autres liens. Ouvrez-le pour la page dédiée /docente/taccuino ; la flèche de l’en-tête revient à l’Espace enseignant. Le Carnet de l’Espace personnel reste distinct. Connectez-vous avec un compte habilité comme enseignant et ouvrez l’espace enseignant depuis la navigation. Vous y trouverez catalogues, travaux attribués, groupes et passations de questionnaires. L’espace personnel reste votre lieu de participation et de réflexion. Le rôle enseignant de CounselorBot ne donne pas automatiquement accès à l’administration technique ni aux autres services ai4educ. Le Carnet de l’enseignant décrit votre rôle et votre pratique habituelle avec six champs facultatifs : matières, expérience résumée, manière d’enseigner, aperçu des fonctions, intérêts pour votre développement et autres informations sur le rôle. La pratique générale est distincte du Contexte de classe, un intérêt personnel d’un objectif pour la classe, une note brève d’un épisode ou travail à conserver. Les notes ne gèrent pas les classes et ne publient pas de catalogues. Enregistrez explicitement. Les objectifs pour la classe utilisent par défaut le carnet enseignant, les autres outils celui de l’étudiant ; dans Options, choisissez Par défaut, Étudiant, Enseignant, Entraînement ou Aucun. Entraînement utilise l’un de vos Carnets d’entraînement (/docente/taccuini-prova) : un étudiant imaginaire pour vous exercer à guider le chat, aussi dans la Boussole ; le modèle reçoit l’instruction explicite qu’il s’agit d’une simulation et vos propres données restent à l’écart. Ce choix ne concerne pas toutes les données de la conversation : la Lecture est distincte et Aucun ne signifie pas anonymat. Le contexte est bref et peut ne pas inclure toutes les notes intégralement : précisez les détails utiles dans le chat. Vous pouvez laisser le carnet vide ; les classes sélectionnées peuvent contribuer aux objectifs pour la classe, selon le contexte choisi. Sous les indications du carnet enseignant, des liens facultatifs ouvrent Groupes et classes, Objectifs personnels, Ligne du temps et Portfolio. Groupes et classes ouvre une fenêtre sans quitter le carnet : choisissez explicitement une classe gérée ou partagée, jamais déduite des notes. Nom, école/organisme, propriétaire et inscrits sont en lecture seule. Le niveau et l’établissement sont enregistrés au changement ; description, méthodes et partage du contexte nécessitent Enregistrer. Annuler abandonne uniquement le brouillon du contexte, pas le niveau ou l’établissement déjà enregistrés. Changer de classe ou fermer demande confirmation si le contexte est modifié et attend tous les enregistrements ; un échec conserve le brouillon et permet de réessayer. Le brouillon privé du carnet reste monté et conservé. Ce choix ne change ni session, ni carnet utilisé par le chat, ni contexte de conversation. La page Classes reste dans la navigation. Les trois autres liens continuent à naviguer sans copier de notes ni créer, enregistrer, publier ou partager du contenu. Les objectifs personnels concernent votre développement, distinct du parcours pour la classe en haut. Avec un brouillon privé modifié, confirmez l’abandon pour quitter ou annulez pour conserver texte, focus et sélection ; attendez l’enregistrement. Un brouillon inchangé ne demande aucune confirmation ; un nouvel onglet préserve le brouillon original. Les six champs sont répartis en trois groupes toujours ouverts : « Mon rôle » (disciplines et expérience), « Ma pratique et mes contextes » (pratique habituelle et fonctions), « Mon développement et autres informations » (intérêts et notes). Tous les champs restent visibles et facultatifs ; les groupes n’imposent pas de parcours.", "Im Lehrkräftebereich ist „Lehrkräfte-Notizbuch“ der erste Einstieg, vor dem DOCENZA-Pfad und den anderen Links. Öffnen Sie es für die eigene Seite /docente/taccuino; der Pfeil in der Kopfzeile führt zum Lehrkräftebereich zurück. Das Notizbuch im persönlichen Bereich bleibt getrennt. Melden Sie sich mit einem für Lehrkräfte freigeschalteten Konto an und öffnen Sie den Lehrkräftebereich über die Navigation. Dort finden Sie Kataloge, versendete Aufgaben, Gruppen und Fragebogendurchführungen. Ihr persönlicher Bereich bleibt Ihr Raum für Teilnahme und Reflexion. Die Lehrkraftrolle in CounselorBot gewährt nicht automatisch Zugriff auf die technische Verwaltung oder andere ai4educ-Dienste. Das Lehrkräfte-Notizbuch beschreibt Ihre Rolle und übliche Praxis in sechs freiwilligen Feldern: Fächer, kurze Erfahrung, übliche Unterrichtsweise, Überblick über Aufgaben, eigene Entwicklungsinteressen und weitere Rollenangaben. Allgemeine Praxis unterscheidet sich vom Klassenkontext, ein persönliches Interesse von einem Klassenziel und eine kurze Notiz von einem Ereignis oder einer aufzubewahrenden Arbeit. Notizen verwalten keine Klassen und veröffentlichen keine Kataloge. Speichern Sie ausdrücklich. Klassenziele nutzen standardmäßig das Lehrkräfte-Notizbuch, andere Werkzeuge das Studierenden-Notizbuch; wählen Sie in den Optionen Standard, Studierende, Lehrkraft, Übung oder Keines. Übung nutzt eines Ihrer Übungs-Notizbücher (/docente/taccuini-prova): eine erfundene lernende Person, um die Gesprächsführung zu üben, auch im Kompass; das Modell erhält die ausdrückliche Anweisung, dass es sich um eine Simulation handelt, und Ihre eigenen Daten bleiben außen vor. Die Wahl betrifft nicht alle Gesprächsdaten: Die Deutung ist getrennt geregelt und Keines bedeutet keine Anonymität. Der Kontext ist kurz und enthält möglicherweise nicht alle Notizen vollständig: Nennen Sie relevante Details im Chat. Das Notizbuch kann leer bleiben; ausgewählte Klassen können je nach gewähltem Kontext trotzdem zu Klassenzielen beitragen. Unter den Hinweisen im Lehrkräfte-Notizbuch führen freiwillige Links zu Gruppen und Klassen, Persönlichen Zielen, Zeitleiste und Portfolio. Gruppen und Klassen öffnet ein Fenster bei offenem Notizbuch: Wählen Sie ausdrücklich eine verwaltete oder geteilte Klasse, niemals aus Notizen abgeleitet. Name, Schule/Organisation, Eigentümer und Mitgliederzahl sind schreibgeschützt. Stufe und Einrichtung werden bei Änderungen gespeichert; Beschreibung, Methoden und Kontextfreigabe erfordern Speichern. Abbrechen verwirft nur den Kontextentwurf, keine bereits gespeicherte Stufe oder Einrichtung. Klassenwechsel und Schließen fragen bei verändertem Kontext nach Bestätigung und warten auf alle Speichervorgänge; Fehler erhalten den Entwurf und erlauben einen neuen Versuch. Der private Notizbuchentwurf bleibt eingebunden und erhalten. Diese Wahl ändert weder Sitzung, Chat-Notizbuch noch Gesprächskontext. Die Seite Klassen bleibt in der Navigation. Die anderen drei Links navigieren weiterhin, ohne Notizen zu kopieren oder Inhalte zu erstellen, speichern, veröffentlichen oder teilen. Persönliche Ziele betreffen Ihre Entwicklung, getrennt vom Klassenpfad oben. Bei ungespeicherten privaten Änderungen bestätigen Sie das Verwerfen zum Verlassen oder brechen ab, um Text, Fokus und Auswahl zu erhalten; warten Sie auf laufendes Speichern. Ein unveränderter Entwurf braucht keine Bestätigung; ein neuer Tab bewahrt den ursprünglichen Entwurf. Die sechs Felder sind in drei stets offene Gruppen gegliedert: „Meine Rolle“ (Fächer und Erfahrung), „Meine Praxis und meine Kontexte“ (übliche Praxis und Aufgaben), „Meine Entwicklung und weitere Angaben“ (Interessen und Notizen). Alle Felder bleiben sichtbar und freiwillig; die Gruppen schreiben keine Reihenfolge vor.", "I Lärarområdet är ”Lärarens anteckningsbok” den första ingången, före DOCENZA-vägen och de andra länkarna. Öppna den för den egna sidan /docente/taccuino; pilen i sidhuvudet återgår till Lärarområdet. Anteckningsboken i det personliga området är separat. Logga in med ett konto som har lärarbehörighet och öppna lärarområdet via navigeringen. Där finns kataloger, skickade uppgifter, grupper och enkätgenomföranden. Det personliga området är fortfarande din plats för deltagande och reflektion. Lärarrollen i CounselorBot ger inte automatiskt tillgång till teknisk administration eller andra ai4educ-tjänster. Lärarens anteckningsbok beskriver din roll och vanliga undervisning med sex valfria fält: ämnen, kort erfarenhet, hur du brukar undervisa, översikt över uppdrag, egna utvecklingsintressen och övrig information om rollen. Vanlig undervisning skiljer sig från Klasskontext, ett personligt intresse från ett klassmål och en kort anteckning från en händelse eller ett arbete att spara. Anteckningarna förvaltar inga klasser och publicerar inga kataloger. Spara uttryckligen. Klassmål använder lärarens anteckningsbok som standard, andra verktyg elevens; välj Standard, Student, Lärare, Övning eller Ingen i Alternativ. Övning använder en av dina övningsanteckningsböcker (/docente/taccuini-prova): en påhittad elev för att öva på att leda chatten, även i kompassen; modellen får en uttrycklig instruktion om att det är en simulering och dina egna uppgifter hålls utanför. Valet gäller inte alla samtalsdata: Tolkning regleras separat och Ingen betyder inte anonymitet. Sammanhanget är kort och kanske inte innehåller alla anteckningar i sin helhet: ange relevanta detaljer i chatten. Anteckningsboken kan vara tom; valda klasser kan ändå bidra till klassmål, beroende på valt sammanhang. Under läraranteckningsbokens hjälptexter finns frivilliga länkar till Grupper och klasser, Personliga mål, Tidslinje och Portfolio. Grupper och klasser öppnar en ruta med anteckningsboken kvar: välj uttryckligen en förvaltad eller delad klass, aldrig härledd från anteckningar. Namn, skola/organisation, ägare och medlemsantal är skrivskyddade. Nivå och institution sparas vid ändring; beskrivning, metoder och kontextdelning kräver Spara. Avbryt kastar bara kontextutkastet, inte redan sparad nivå eller institution. Klassbyte och stängning kräver bekräftelse vid ändrad kontext och väntar på alla sparanden; fel bevarar utkastet och erbjuder nytt försök. Det privata anteckningsutkastet förblir monterat och bevarat. Valet ändrar inte session, anteckningsbok i chatten eller samtalskontext. Sidan Klasser finns kvar i navigeringen. De andra tre länkarna navigerar som förut utan att kopiera anteckningar eller skapa, spara, publicera eller dela innehåll. Personliga mål gäller din utveckling, skild från klassens målväg överst. Vid osparade privata ändringar bekräftar du att kasta dem för att lämna eller avbryter för att behålla text, fokus och markering; vänta på sparandet. Ett oförändrat utkast kräver ingen bekräftelse; en ny flik bevarar ursprungsutkastet. De sex fälten är ordnade i tre grupper som alltid är öppna: ”Min roll” (ämnen och erfarenhet), ”Min undervisning och mina sammanhang” (vanlig undervisning och uppdrag), ”Min utveckling och övrig information” (intressen och anteckningar). Alla fält förblir synliga och valfria; grupperna kräver ingen bestämd arbetsgång."],
    teacher2Title: ['Gestire gruppi e classi', 'Manage groups and classes', 'Gestionar grupos y clases', 'Gérer groupes et classes', 'Gruppen und Klassen verwalten', 'Hantera grupper och klasser'],
    teacher2Body: ["In “Gruppi e classi che gestisco” crea un gruppo, indica il contesto e distribuisci il codice o il collegamento di invito. Puoi lavorare con scuola, università e formazione degli adulti. Controlla i partecipanti e le eventuali condivisioni di gestione; le tue iscrizioni personali si trovano invece in “I miei gruppi/classi”. Nell’area somministrazioni prepara i questionari disponibili e consulta gli esiti secondo le autorizzazioni del gruppo. Se l’amministratore ti ha associato a un istituto, apri “Orientamento dell’istituto”: insieme agli altri docenti puoi creare, descrivere, riordinare e archiviare le categorie. Salva esplicitamente le modifiche; in caso di conflitto ricarica l’elenco prima di riprovare. In “Contatti e appuntamenti” apri il menu a tre punti di un contenuto e scegli “Assegna categorie”. Puoi selezionarne più di una e salvare; i filtri degli studenti useranno queste associazioni. Recapiti, date e certificazione mantengono la gestione attuale. Se il caricamento delle classi, del Taccuino del docente o della selezione classi nella chat fallisce, usa Riprova: un errore non indica dati vuoti o persi. Le riletture conservano dati, bozze non salvate e classi selezionate. Prima della prima lettura riuscita non puoi creare gruppi o salvare il taccuino. Il taccuino e il selettore offrono Aggiorna; un errore recuperabile del selettore non blocca la chat. I salvataggi rimangono espliciti. In Gruppi e classi, la creazione precede l’elenco. Ogni scheda classe parte aperta e puoi comprimerla da tastiera senza perdere la bozza. Fascia, istituto e contesto precedono inviti e gestione: fascia e istituto si salvano al cambio, mentre descrizione, metodologie e condivisione del contesto richiedono Salva. Nome e scuola/ente restano in sola lettura dopo la creazione. Stato ed errori restano visibili anche a scheda chiusa; Riprova salvataggio ripete l’operazione fallita. Una risposta tardiva non cancella il testo scritto durante il salvataggio.", "In the groups and classes you manage, create a group, specify its context and distribute the invitation code or link. You can work with schools, universities and adult education. Check participants and any shared management access; your own memberships appear in “My groups/classes”. In the assessment area, prepare available questionnaires and consult results according to group permissions. If an administrator has linked you to an institution, open “Institution guidance”: together with its other teachers, you can create, describe, reorder and archive categories. Save changes explicitly; if a conflict occurs, reload the list before retrying. Under “Contacts and appointments”, open an item’s three-dot menu and choose “Assign categories”. Select one or more and save; student filters use these assignments. Contact details, dates and certification retain their existing management. If classes, the teacher notebook or the chat class selector fail to load, use Try again: an error does not mean data is empty or lost. Rereads preserve data, unsaved drafts and selected classes. Before the first successful read you cannot create groups or save the notebook. The notebook and selector offer Refresh; a recoverable selector error does not block the chat. Saving remains explicit. In Groups and classes, creation comes before the list. Each class starts expanded and can be collapsed using the keyboard without losing its draft. Level, institution and context come before invitations and management: level and institution save when changed; description, methodologies and context sharing require Save. Name and school/organisation remain read-only after creation. Status and errors remain visible when collapsed; Retry saving repeats the failed operation. A late response does not erase text entered while saving.", "En los grupos y clases que gestionas, crea un grupo, indica el contexto y distribuye el código o enlace de invitación. Puedes trabajar en escuelas, universidades y formación de adultos. Revisa los participantes y los accesos de gestión compartida; tus inscripciones personales están en “Mis grupos/clases”. En el área de administración de cuestionarios, prepara los disponibles y consulta los resultados según los permisos del grupo. Si un administrador te ha asociado a una institución, abre “Orientación de la institución”: junto con sus docentes puedes crear, describir, ordenar y archivar categorías. Guarda los cambios explícitamente; si hay un conflicto, recarga la lista antes de reintentar. En “Contactos y citas”, abre el menú de tres puntos de un contenido y elige “Asignar categorías”. Selecciona una o varias y guarda; los filtros del alumnado usan estas asociaciones. Los datos de contacto, fechas y certificación mantienen su gestión actual. Si falla la carga de las clases, del cuaderno docente o de la selección de clases en la chat, usa Reintentar: un error no significa que los datos estén vacíos o perdidos. Las relecturas conservan los datos, los borradores sin guardar y las clases seleccionadas. Antes de la primera lectura correcta no puedes crear grupos ni guardar el cuaderno. El cuaderno y el selector ofrecen Actualizar; un error recuperable del selector no bloquea la chat. Guardar sigue siendo una acción explícita. En Grupos y clases, la creación precede a la lista. Cada ficha empieza abierta y se puede contraer con el teclado sin perder el borrador. La franja, el instituto y el contexto preceden a las invitaciones y la gestión: la franja y el instituto se guardan al cambiarlos; la descripción, las metodologías y compartir el contexto requieren Guardar. El nombre y la escuela o entidad son de solo lectura tras la creación. El estado y los errores siguen visibles al contraer; Reintentar guardado repite la operación fallida. Una respuesta tardía no borra el texto escrito mientras se guardaba.", "Dans les groupes et classes que vous gérez, créez un groupe, précisez son contexte et diffusez le code ou lien d’invitation. Vous pouvez travailler dans le secondaire, à l’université et en formation d’adultes. Vérifiez les participants et les éventuels accès de gestion partagée ; vos inscriptions personnelles figurent dans « Mes groupes/classes ». Dans l’espace de passation, préparez les questionnaires disponibles et consultez les résultats selon les droits du groupe. Si un administrateur vous a associé à un établissement, ouvrez son espace d’orientation : avec les autres enseignants, vous pouvez créer, décrire, réordonner et archiver les catégories. Enregistrez explicitement les modifications ; en cas de conflit, rechargez la liste avant de réessayer. Dans « Contacts et rendez-vous », ouvrez le menu à trois points d’un contenu et choisissez « Attribuer des catégories ». Sélectionnez-en une ou plusieurs et enregistrez ; les filtres des élèves utilisent ces associations. La gestion des coordonnées, dates et certifications reste inchangée. Si le chargement des classes, du carnet de l’enseignant ou du sélecteur de classes du chat échoue, utilisez Réessayer : une erreur ne signifie pas que les données sont vides ou perdues. Les relectures préservent les données, les brouillons non enregistrés et les classes sélectionnées. Avant la première lecture réussie, vous ne pouvez pas créer de groupes ni enregistrer le carnet. Le carnet et le sélecteur proposent Actualiser ; une erreur récupérable du sélecteur ne bloque pas le chat. L’enregistrement reste explicite. Dans Groupes et classes, la création précède la liste. Chaque fiche est ouverte au départ et peut être réduite au clavier sans perdre le brouillon. Le niveau, l’établissement et le contexte précèdent les invitations et la gestion : le niveau et l’établissement sont enregistrés dès leur modification ; la description, les méthodes et le partage du contexte nécessitent Enregistrer. Le nom et l’école ou organisme restent en lecture seule après la création. Les états et erreurs restent visibles dans une fiche réduite ; Réessayer l’enregistrement répète l’opération échouée. Une réponse tardive n’efface pas le texte saisi pendant l’enregistrement.", "Erstellen Sie unter den von Ihnen verwalteten Gruppen und Klassen eine Gruppe, geben Sie den Kontext an und verteilen Sie den Einladungscode oder -link. Möglich sind Schule, Hochschule und Erwachsenenbildung. Prüfen Sie Teilnehmende und geteilte Verwaltungsrechte; eigene Mitgliedschaften stehen unter „Meine Gruppen/Klassen“. Bereiten Sie im Durchführungsbereich verfügbare Fragebögen vor und lesen Sie Ergebnisse gemäß den Gruppenberechtigungen. Wenn die Administration Sie einer Einrichtung zugeordnet hat, öffnen Sie deren Orientierungsbereich: Gemeinsam mit den anderen Lehrkräften können Sie Kategorien erstellen, beschreiben, sortieren und archivieren. Speichern Sie Änderungen ausdrücklich; laden Sie bei einem Konflikt die Liste vor einem neuen Versuch neu. Öffne unter „Kontakte und Termine“ das Dreipunktmenü eines Inhalts und wähle „Kategorien zuordnen“. Wähle eine oder mehrere und speichere; die Lernenden filtern nach diesen Zuordnungen. Kontaktdaten, Termine und Zertifizierung werden weiterhin wie bisher verwaltet. Wenn Klassen, Lehrkräfte-Notizbuch oder Klassenauswahl im Chat nicht geladen werden, wählen Sie Erneut versuchen: Ein Fehler bedeutet keine leeren oder verlorenen Daten. Erneutes Lesen bewahrt Daten, ungespeicherte Entwürfe und ausgewählte Klassen. Vor dem ersten erfolgreichen Lesen können Sie keine Gruppen erstellen und das Notizbuch nicht speichern. Notizbuch und Auswahl bieten Aktualisieren; ein behebbarer Auswahlfehler blockiert den Chat nicht. Das Speichern bleibt ausdrücklich. Unter Gruppen und Klassen steht das Erstellen vor der Liste. Jede Klassenkarte ist anfangs geöffnet und lässt sich per Tastatur zuklappen, ohne den Entwurf zu verlieren. Stufe, Einrichtung und Kontext stehen vor Einladungen und Verwaltung: Stufe und Einrichtung werden bei Auswahländerungen gespeichert; Beschreibung, Methoden und Kontextfreigabe benötigen Speichern. Name und Schule oder Organisation bleiben nach dem Erstellen schreibgeschützt. Status und Fehler bleiben auch zugeklappt sichtbar; Speichern erneut versuchen wiederholt den fehlgeschlagenen Vorgang. Eine verspätete Antwort löscht keinen während des Speicherns eingegebenen Text.", "Skapa en grupp bland de grupper och klasser du hanterar, ange sammanhang och dela inbjudningskoden eller länken. Du kan arbeta med skola, universitet och vuxenutbildning. Kontrollera deltagare och eventuell delad förvaltning; dina egna medlemskap finns under ”Mina grupper/klasser”. Förbered tillgängliga enkäter i genomförandeområdet och läs resultaten enligt gruppens behörigheter. Om en administratör har kopplat dig till en institution kan du öppna institutionens vägledning: tillsammans med övriga lärare kan du skapa, beskriva, ordna och arkivera kategorier. Spara ändringar uttryckligen; vid en konflikt laddar du om listan innan du försöker igen. Öppna innehållets trepunktsmeny under ”Kontakter och möten” och välj ”Tilldela kategorier”. Välj en eller flera och spara; elevernas filter använder dessa kopplingar. Kontaktuppgifter, datum och certifiering hanteras som tidigare. Om klasser, lärarens anteckningsbok eller klassväljaren i chatten inte kan laddas, välj Försök igen: ett fel betyder inte att data är tomma eller förlorade. Omläsning bevarar data, osparade utkast och valda klasser. Före den första lyckade läsningen kan du inte skapa grupper eller spara anteckningsboken. Anteckningsboken och väljaren erbjuder Uppdatera; ett återställbart fel i väljaren blockerar inte chatten. Sparande kräver fortfarande ett uttryckligt val. I Grupper och klasser visas skapandet före listan. Varje klasskort är öppet från början och kan fällas ihop med tangentbordet utan att utkastet försvinner. Nivå, institution och kontext visas före inbjudningar och hantering: nivå och institution sparas när valet ändras; beskrivning, arbetssätt och kontextdelning kräver Spara. Namn och skola eller organisation är skrivskyddade efter skapandet. Status och fel syns även i ett hopfällt kort; Försök spara igen upprepar den misslyckade åtgärden. Ett sent svar tar inte bort text som skrivits under sparandet."],
    teacher3Title: ['Preparare i cataloghi', 'Prepare the catalogs', 'Preparar los catálogos', 'Préparer les catalogues', 'Kataloge vorbereiten', 'Förbered katalogerna'],
    teacher3Body: ['Apri separatamente “Catalogo obiettivi”, “Strategie” e “Libri, film e altri materiali”. Crea o modifica una proposta, controlla lingua, destinatari e contenuto, quindi pubblicala. Strategie e materiali possono essere pubblicati direttamente dal docente. Gli obiettivi possono essere pubblicati nei gruppi gestiti; quelli destinati al catalogo comune richiedono revisione amministrativa. Pubblicare una proposta non significa assegnarla né adottarla come obiettivo dello studente.', 'Open the goal catalog, strategies, and books, films and other resources separately. Create or edit a proposal, check its language, audience and content, then publish it. Teachers can publish strategies and resources directly. Goals can be published to managed groups; goals for the common catalog require administrative review. Publishing a proposal neither assigns it nor adopts it as a student’s goal.', 'Abre por separado el catálogo de objetivos, las estrategias y los libros, películas y otros materiales. Crea o edita una propuesta, revisa idioma, destinatarios y contenido y publícala. El docente puede publicar estrategias y materiales directamente. Los objetivos se pueden publicar en los grupos gestionados; el catálogo común requiere revisión administrativa. Publicar no asigna la propuesta ni la adopta como objetivo del estudiante.', 'Ouvrez séparément le catalogue d’objectifs, les stratégies et les livres, films et autres ressources. Créez ou modifiez une proposition, vérifiez langue, public et contenu, puis publiez-la. Les enseignants peuvent publier directement stratégies et ressources. Les objectifs peuvent être publiés dans les groupes gérés ; le catalogue commun exige une validation administrative. Publier une proposition ne l’attribue pas et ne l’adopte pas comme objectif de l’étudiant.', 'Öffnen Sie Zielkatalog, Strategien sowie Bücher, Filme und weitere Materialien getrennt. Erstellen oder bearbeiten Sie einen Vorschlag, prüfen Sie Sprache, Zielgruppe und Inhalt und veröffentlichen Sie ihn. Lehrkräfte können Strategien und Materialien direkt veröffentlichen. Ziele können in verwalteten Gruppen veröffentlicht werden; der gemeinsame Katalog erfordert eine administrative Prüfung. Eine Veröffentlichung weist den Vorschlag weder zu noch übernimmt sie ihn als persönliches Lernziel.', 'Öppna målkatalogen, strategier samt böcker, filmer och annat material var för sig. Skapa eller redigera ett förslag, kontrollera språk, målgrupp och innehåll och publicera det. Lärare kan publicera strategier och material direkt. Mål kan publiceras i hanterade grupper; den gemensamma katalogen kräver administrativ granskning. Publicering tilldelar inte förslaget och gör det inte till elevens personliga mål.'],
    teacher4Title: ['Assegnare una proposta o un’attività', 'Assign a proposal or activity', 'Asignar una propuesta o actividad', 'Attribuer une proposition ou activité', 'Einen Vorschlag oder eine Aktivität zuweisen', 'Tilldela ett förslag eller en aktivitet'],
    teacher4Body: ['Da un contenuto pubblicato premi “Assegna”. Scegli gruppo e destinatario, scrivi le indicazioni e distingui una proposta da esplorare da un’attività con restituzione attesa. Puoi indicare scadenza e richiesta di restituzione. Un’assegnazione al gruppo può precedere le iscrizioni: chi entra dopo trova quelle ancora attive. Lo studente decide se adottare un obiettivo e come collegarlo al proprio lavoro; l’invio non compie queste scelte al suo posto.', 'Select “Assign” on published content. Choose the group and recipient, add instructions and distinguish a proposal to explore from an activity requiring a response. You can specify a due date and response prompt. Group assignments can precede enrollment: later participants see those still active. The student decides whether to adopt a goal and how to connect it to personal work; sending an assignment does not make those choices for them.', 'Pulsa “Asignar” en un contenido publicado. Elige grupo y destinatario, escribe las indicaciones y distingue una propuesta para explorar de una actividad con entrega esperada. Puedes indicar plazo y consigna de entrega. La asignación al grupo puede preceder a las inscripciones: quienes entren después encontrarán las activas. El estudiante decide si adopta un objetivo y cómo lo vincula a su trabajo; el envío no decide por él.', 'Sur un contenu publié, choisissez « Attribuer ». Sélectionnez groupe et destinataire, ajoutez des indications et distinguez une proposition à explorer d’une activité avec un travail attendu. Vous pouvez préciser une échéance et une consigne de restitution. Une attribution au groupe peut précéder les inscriptions : les nouveaux participants retrouvent celles encore actives. L’étudiant choisit d’adopter un objectif et de le relier à son travail ; l’envoi ne fait pas ces choix à sa place.', 'Wählen Sie bei veröffentlichten Inhalten „Zuweisen“. Wählen Sie Gruppe und Empfänger, ergänzen Sie Hinweise und unterscheiden Sie einen Erkundungsvorschlag von einer Aktivität mit erwarteter Abgabe. Frist und Rückmeldeauftrag sind optional. Gruppenzuweisungen können vor dem Beitritt erfolgen: Später Beitretende sehen weiterhin aktive Zuweisungen. Lernende entscheiden selbst, ob sie ein Ziel übernehmen und mit ihrer Arbeit verknüpfen; das Versenden trifft diese Entscheidungen nicht für sie.', 'Välj ”Tilldela” på publicerat innehåll. Välj grupp och mottagare, skriv instruktioner och skilj mellan ett förslag att utforska och en aktivitet med förväntad redovisning. Du kan ange deadline och redovisningsfråga. Grupptilldelningar kan skapas före anslutning: senare deltagare ser dem som fortfarande är aktiva. Eleven väljer själv om ett mål ska antas och kopplas till arbetet; tilldelningen gör inte dessa val åt eleven.'],
    teacher5Title: ['Leggere le restituzioni e dare riscontro', 'Read responses and give feedback', 'Leer entregas y dar comentarios', 'Lire les travaux et apporter un retour', 'Abgaben lesen und Rückmeldung geben', 'Läs redovisningar och ge återkoppling'],
    teacher5Body: ['In “Assegnazioni inviate” apri le restituzioni della singola attività. Leggi il testo e l’eventuale copia del lavoro di Portfolio che lo studente ha scelto di condividere, scrivi un riscontro e invialo. Lo studente lo ritrova nell’assegnazione e nel riepilogo del percorso. La copia condivisa non si aggiorna quando cambia il lavoro personale: serve una nuova condivisione. Lo studente può ritirare la restituzione mantenendo il proprio lavoro.', 'In sent assignments, open the responses for an activity. Read the text and any Portfolio copy the student chose to share, write feedback and send it. The student finds it in the assignment and journey overview. The shared copy does not update when personal work changes: it must be shared again. Students can withdraw a response while keeping their personal work.', 'En las asignaciones enviadas, abre las entregas de la actividad. Lee el texto y la copia del Portafolio que el estudiante haya elegido compartir, escribe un comentario y envíalo. El estudiante lo encontrará en la asignación y en el resumen de su recorrido. La copia compartida no cambia al editar el trabajo personal: debe compartirse de nuevo. El estudiante puede retirar la entrega y conservar su trabajo.', 'Dans les travaux attribués, ouvrez les restitutions d’une activité. Lisez le texte et l’éventuelle copie du Portfolio que l’étudiant a choisi de partager, rédigez un retour et envoyez-le. L’étudiant le retrouve dans l’activité et la vue d’ensemble de son parcours. La copie partagée ne suit pas les modifications du travail personnel : un nouveau partage est nécessaire. L’étudiant peut retirer sa restitution tout en conservant son travail.', 'Öffnen Sie bei den versendeten Aufgaben die Abgaben einer Aktivität. Lesen Sie den Text und die gegebenenfalls geteilte Portfolio-Kopie, schreiben Sie eine Rückmeldung und senden Sie sie. Lernende finden sie in der Aufgabe und der Wegübersicht. Änderungen an der persönlichen Arbeit aktualisieren die geteilte Kopie nicht: Sie muss erneut geteilt werden. Lernende können eine Abgabe zurückziehen und ihre persönliche Arbeit behalten.', 'Öppna redovisningarna för en aktivitet bland skickade uppgifter. Läs texten och eventuell Portfoliokopia som eleven valt att dela, skriv återkoppling och skicka den. Eleven hittar den i uppgiften och i översikten över sin väg. Den delade kopian uppdateras inte när det personliga arbetet ändras: den måste delas igen. Eleven kan dra tillbaka redovisningen och behålla sitt personliga arbete.'],
    teacher6Title: ['Capire la condivisione', 'Understand sharing', 'Entender qué se comparte', 'Comprendre le partage', 'Freigaben verstehen', 'Förstå delning'],
    teacher6Body: ['I gestori del gruppo possono già consultare Taccuino, risultati e relative conversazioni. Per gli obiettivi personali, invece, il docente vede i riepiloghi esplicitamente condivisi con il gruppo. Nel flusso delle assegnazioni vede soltanto la restituzione condivisa con lui: non le bozze, le date di lavoro personali, il diario privato o gli obiettivi collegati. Revocare un’assegnazione e ritirare una restituzione sono azioni distinte; nessuna cancella automaticamente il lavoro personale dello studente.', 'Group managers already have access to the Notebook, results and related conversations. For personal goals, teachers see summaries explicitly shared with the group. In the assignment workflow, they only see the response shared with them: not drafts, personal planning dates, private diary entries or linked goals. Revoking an assignment and withdrawing a response are distinct actions; neither automatically deletes the student’s personal work.', 'Los responsables del grupo ya pueden consultar el Cuaderno, los resultados y las conversaciones relacionadas. Para los objetivos personales, el docente ve los resúmenes compartidos explícitamente con el grupo. En las asignaciones solo ve la entrega compartida con él: no los borradores, fechas personales de trabajo, diario privado u objetivos vinculados. Revocar una asignación y retirar una entrega son acciones distintas; ninguna elimina automáticamente el trabajo personal del estudiante.', 'Les responsables du groupe peuvent déjà consulter le Carnet, les résultats et les conversations associées. Pour les objectifs personnels, l’enseignant voit les bilans explicitement partagés avec le groupe. Dans les activités attribuées, il voit uniquement le travail partagé avec lui : pas les brouillons, dates personnelles de travail, journal privé ou objectifs liés. Révoquer une activité et retirer une restitution sont deux actions distinctes ; aucune ne supprime automatiquement le travail personnel de l’étudiant.', 'Gruppenverantwortliche können bereits Notizbuch, Ergebnisse und zugehörige Gespräche einsehen. Bei persönlichen Zielen sehen Lehrkräfte ausdrücklich mit der Gruppe geteilte Zusammenfassungen. Im Zuweisungsablauf sehen sie nur die mit ihnen geteilte Abgabe: keine Entwürfe, persönlichen Planungstermine, privaten Tagebucheinträge oder verknüpften Ziele. Das Widerrufen einer Zuweisung und das Zurückziehen einer Abgabe sind getrennte Aktionen; keine löscht automatisch die persönliche Arbeit.', 'Gruppansvariga har redan tillgång till Anteckningsboken, resultat och tillhörande samtal. För personliga mål ser läraren sammanfattningar som uttryckligen delats med gruppen. I tilldelningsflödet ser läraren bara den redovisning som delats med hen: inte utkast, personliga planeringsdatum, privat dagbok eller länkade mål. Att återkalla en uppgift och att dra tillbaka en redovisning är olika åtgärder; ingen raderar automatiskt elevens personliga arbete.'],
    teacher7Title: ['Bussola, assistente ed eventi significativi', 'Compass, assistant and significant events', 'Brújula, asistente y eventos significativos', 'Boussole, assistant et événements significatifs', 'Kompass, Assistent und bedeutsame Ereignisse', 'Kompass, assistent och betydelsefulla händelser'],
    teacher7Body: ["La Bussola aiuta a scegliere un punto di partenza; l’assistente risponde sull’uso della piattaforma tenendo conto del ruolo docente. Per accompagnare la riflessione sono disponibili “Evento significativo di studio” e “Evento significativo professionale”. Il secondo è utile anche per rileggere una tua lezione o un episodio di lavoro. Entrambi propongono sei passi di riflessione e una sintesi finale da rivedere e salvare come tappa nella Linea del tempo, senza questionari o punteggi. Sono percorsi diversi dagli eventi del calendario. Per chat, Taccuino, Obiettivi e strumenti personali puoi passare alla guida Uso personale / studente. Dall’Area docenti puoi anche avviare “Obiettivi per la mia classe”, scegliendo le classi di riferimento: il percorso collega obiettivo, attività e valutazione. Il PDF e le Flashcard si aprono dall’Area personale e strumenti, disponibile nella presentazione insieme a Bussola, Analisi questionari e Percorsi guidati.", "The Compass helps choose a starting point; the assistant explains platform use with the teacher role in mind. “Significant study event” and “Significant professional event” support reflection. The latter also suits reviewing a lesson you taught or a work episode. Both offer six reflection steps and a final summary to review and save as a milestone in the Timeline, without questionnaires or scores. These paths are distinct from calendar events. For chat, Notebook, Goals and personal tools, switch to the Personal use / student guide. From the Teacher area you can also start Objectives for my class, selecting the relevant classes: the path connects objective, activities and assessment. PDF study and Flashcards open from Personal area and tools, available in the introduction alongside Compass, Questionnaire analysis and Guided paths.", "La Brújula ayuda a elegir un punto de partida; el asistente explica el uso de la plataforma teniendo en cuenta el rol docente. “Evento significativo de estudio” e “Evento significativo profesional” acompañan la reflexión. El segundo también permite revisar una clase impartida o un episodio laboral. Ambos ofrecen seis pasos de reflexión y una síntesis final que se revisa y se guarda como etapa en la Línea del tiempo, sin cuestionarios ni puntuaciones. Son distintos de los eventos del calendario. Para chat, Cuaderno, Objetivos y herramientas personales, consulta la guía Uso personal / estudiante. Desde el Área docente también puedes iniciar Objetivos para mi clase y seleccionar las clases: el recorrido conecta objetivo, actividades y evaluación. El estudio de PDF y las tarjetas de repaso se abren desde Área personal y herramientas, junto a Brújula, Análisis de cuestionarios y Recorridos guiados en la presentación.", "La Boussole aide à choisir un point de départ ; l’assistant explique l’usage de la plateforme en tenant compte du rôle enseignant. Les parcours « Événement significatif d’étude » et « Événement significatif professionnel » accompagnent la réflexion. Le second permet aussi de revenir sur un cours donné ou un épisode professionnel. Tous deux proposent six étapes et une synthèse finale à relire et à enregistrer comme étape dans la Ligne du temps, sans questionnaire ni score. Ils sont distincts des événements du calendrier. Pour le chat, le Carnet, les Objectifs et les outils personnels, choisissez le guide Usage personnel / étudiant. Depuis l’Espace enseignant, vous pouvez aussi lancer Objectifs pour ma classe en sélectionnant les classes concernées : le parcours relie objectif, activités et évaluation. L’étude de PDF et les fiches de révision se trouvent dans Espace personnel et outils, aux côtés de Boussole, Analyse des questionnaires et Parcours guidés dans la présentation.", "Der Kompass hilft bei der Wahl eines Einstiegs; der Assistent erklärt die Plattform unter Berücksichtigung der Lehrkraftrolle. „Bedeutsames Studienereignis“ und „Bedeutsames berufliches Ereignis“ unterstützen die Reflexion. Letzteres eignet sich auch für den Rückblick auf eine eigene Unterrichtsstunde oder berufliche Situation. Beide bieten sechs Reflexionsschritte und eine abschließende Zusammenfassung, die man überarbeitet und als Etappe in der Zeitleiste speichert, ohne Fragebögen oder Punktwerte. Sie sind von Kalenderereignissen zu unterscheiden. Für Chat, Notizbuch, Ziele und persönliche Werkzeuge wechseln Sie zur Anleitung für persönliche Nutzung. Im Lehrkräftebereich können Sie auch Ziele für meine Klasse starten und die betreffenden Klassen auswählen: Der Weg verbindet Ziel, Aktivitäten und Bewertung. PDF-Lernen und Lernkarten finden Sie im Persönlichen Bereich und Werkzeuge, neben Kompass, Fragebogenauswertung und Geführten Wegen in der Einführung.", "Kompassen hjälper till att välja en startpunkt; assistenten förklarar plattformen med hänsyn till lärarrollen. ”Betydelsefull studiehändelse” och ”Betydelsefull yrkeshändelse” stödjer reflektion. Det senare passar också för att se tillbaka på en egen lektion eller arbetshändelse. Båda har sex reflektionssteg och en avslutande sammanfattning att granska och spara som etapp på tidslinjen, utan enkäter eller poäng. De skiljer sig från kalenderhändelser. Byt till guiden Personligt bruk / elev för chatt, Anteckningsbok, Mål och personliga verktyg. Från Lärarområdet kan du också starta Mål för min klass och välja berörda klasser: vägen kopplar samman mål, aktiviteter och bedömning. PDF-studier och flashcards öppnas från Personligt område och verktyg, bredvid Kompass, Enkätanalys och Guidade vägar i presentationen."],
    teacher8Title: ['Forum della classe e moderazione', 'Class forum and moderation', 'Foro de la clase y moderación', 'Forum de la classe et modération', 'Klassenforum und Moderation', 'Klassens forum och moderering'],
    teacher8Body: ["Apri la classe e scegli la scheda «Forum»: puoi aprire discussioni, rispondere e moderare dalla discussione aperta. «Metti in evidenza» tiene un tema in cima, «Chiudi discussione» blocca le risposte, «Nascondi…» chiede un motivo visibile solo ai docenti e «Ripristina» lo annulla. In «Strumenti e counselor», l’interruttore Forum e le «Opzioni forum» decidono se gli studenti possono aprire discussioni e se i loro messaggi vanno approvati prima di essere visibili; un’opzione «Bloccato dall’amministratore» non si può cambiare. Con l’approvazione attiva, «In attesa (n)» elenca i messaggi da approvare o rifiutare con un motivo; i messaggi dei docenti non vengono mai trattenuti. Su un messaggio di uno studente, «Silenzia autore» chiede un motivo e una data di fine facoltativa; «Studenti silenziati» elenca i silenziamenti attivi da rimuovere. Ogni azione entra nel «Registro moderazione», visibile solo ai docenti della classe e agli amministratori, senza il testo dei messaggi e senza modifiche o cancellazioni. In una classe disattivata il forum resta un archivio in sola lettura, senza moderazione. Nessun modello AI, neppure locale, legge il forum; i messaggi restano fuori da esportazioni per la ricerca, registri di sessione e PDF.", "Open the class and choose the “Forum” tab: you can open discussions, reply and moderate from the open discussion. “Pin” keeps a topic at the top, “Close discussion” stops replies, “Hide…” asks for a reason visible to teachers only, and “Restore” undoes it. In “Tools & counselors”, the Forum switch and “Forum options” decide whether students can open discussions and whether their messages need approval before they are visible; an option marked “Locked by administrator” cannot be changed. With approval on, “Pending (n)” lists messages to approve or reject with a reason; teachers’ own messages are never held. On a student’s message, “Mute author” asks for a reason and an optional end date; “Muted students” lists active mutes you can lift. Every action goes to the “Moderation log”, visible only to the class’s teachers and administrators, with no message text and no edit or delete. In a deactivated class the forum stays a read-only archive with no moderation. No AI model, not even a local one, reads the forum; messages stay out of research exports, session records and PDFs.", "Abre la clase y elige la pestaña «Foro»: puedes abrir discusiones, responder y moderar desde la discusión abierta. «Fijar» mantiene un tema arriba, «Cerrar discusión» impide responder, «Ocultar…» pide un motivo visible solo para los docentes y «Restaurar» lo deshace. En «Herramientas y counselors», el interruptor Foro y las «Opciones del foro» deciden si los estudiantes pueden abrir discusiones y si sus mensajes requieren aprobación antes de ser visibles; una opción «Bloqueado por el administrador» no se puede cambiar. Con la aprobación activa, «Pendientes (n)» lista los mensajes que aprobar o rechazar con un motivo; los mensajes de los docentes nunca quedan retenidos. En el mensaje de un estudiante, «Silenciar autor» pide un motivo y una fecha final opcional; «Estudiantes silenciados» lista los silencios activos que puedes quitar. Cada acción entra en el «Registro de moderación», visible solo para los docentes de la clase y los administradores, sin el texto de los mensajes y sin edición ni borrado. En una clase desactivada el foro queda como archivo de solo lectura, sin moderación. Ningún modelo de IA, ni siquiera local, lee el foro; los mensajes quedan fuera de las exportaciones de investigación, los registros de sesión y los PDF.", "Ouvrez la classe et choisissez l’onglet « Forum » : vous pouvez ouvrir des discussions, répondre et modérer depuis la discussion ouverte. « Épingler » garde un sujet en haut, « Fermer la discussion » bloque les réponses, « Masquer… » demande un motif visible uniquement par les enseignants et « Rétablir » l’annule. Dans « Outils et counselors », l’interrupteur Forum et les « Options du forum » décident si les élèves peuvent ouvrir des discussions et si leurs messages doivent être approuvés avant d’être visibles ; une option « Verrouillé par l’administrateur » ne peut pas être modifiée. Avec l’approbation active, « En attente (n) » liste les messages à approuver ou à refuser avec un motif ; les messages des enseignants ne sont jamais retenus. Sur le message d’un élève, « Mettre l’auteur en silence » demande un motif et une date de fin facultative ; « Élèves mis en silence » liste les silences actifs à lever. Chaque action entre dans le « Journal de modération », visible uniquement par les enseignants de la classe et les administrateurs, sans le texte des messages et sans modification ni suppression. Dans une classe désactivée, le forum reste une archive en lecture seule, sans modération. Aucun modèle d’IA, même local, ne lit le forum ; les messages restent exclus des exports de recherche, des journaux de session et des PDF.", "Öffnen Sie die Klasse und wählen Sie den Reiter „Forum“: Dort eröffnen Sie Diskussionen, antworten und moderieren in der geöffneten Diskussion. „Anheften“ hält ein Thema oben, „Diskussion schließen“ verhindert Antworten, „Ausblenden…“ verlangt einen nur für Lehrkräfte sichtbaren Grund und „Wiederherstellen“ macht es rückgängig. Unter „Werkzeuge und Counselors“ legen der Forum-Schalter und die „Forumoptionen“ fest, ob Lernende Diskussionen eröffnen dürfen und ob ihre Nachrichten vor der Veröffentlichung freigegeben werden müssen; eine Option mit „Von der Administration gesperrt“ lässt sich nicht ändern. Bei aktiver Freigabe listet „Ausstehend (n)“ die Nachrichten auf, die Sie freigeben oder mit einem Grund ablehnen; Nachrichten von Lehrkräften werden nie zurückgehalten. Bei der Nachricht einer lernenden Person verlangt „Autor stummschalten“ einen Grund und ein optionales Enddatum; „Stummgeschaltete Lernende“ listet aktive Stummschaltungen, die Sie aufheben können. Jede Aktion landet im „Moderationsprotokoll“, das nur Lehrkräfte der Klasse und Administratoren sehen, ohne Nachrichtentext und ohne Bearbeiten oder Löschen. In einer deaktivierten Klasse bleibt das Forum ein schreibgeschütztes Archiv ohne Moderation. Kein KI-Modell, auch kein lokales, liest das Forum; Nachrichten bleiben aus Forschungsexporten, Sitzungsprotokollen und PDFs ausgeschlossen.", "Öppna klassen och välj fliken ”Forum”: där startar du diskussioner, svarar och modererar i den öppnade diskussionen. ”Fäst” håller ett ämne överst, ”Stäng diskussionen” stoppar svar, ”Dölj…” kräver en anledning som bara lärare ser och ”Återställ” ångrar det. Under ”Verktyg och counselors” avgör forumreglaget och ”Forumalternativ” om elever får starta diskussioner och om deras meddelanden måste godkännas innan de visas; ett alternativ märkt ”Låst av administratören” går inte att ändra. Med godkännande påslaget listar ”Väntande (n)” meddelanden att godkänna eller avvisa med en anledning; lärares egna meddelanden hålls aldrig kvar. På en elevs meddelande kräver ”Tysta författare” en anledning och ett valfritt slutdatum; ”Tystade elever” listar aktiva tystningar som du kan ta bort. Varje åtgärd hamnar i ”Modereringslogg”, som bara klassens lärare och administratörer ser, utan meddelandetext och utan redigering eller radering. I en avaktiverad klass förblir forumet ett skrivskyddat arkiv utan moderering. Ingen AI-modell, inte heller en lokal, läser forumet; meddelandena hålls utanför forskningsexporter, sessionsloggar och PDF:er."],
} as const satisfies Record<string, readonly [string, string, string, string, string, string]>;

export type GuideAudienceKey = keyof typeof text;
export function guideAudienceText(lang: string, key: GuideAudienceKey): string {
    const index = ['it', 'en', 'es', 'fr', 'de', 'sv'].indexOf(lang);
    return text[key][index < 0 ? 1 : index];
}
